import * as THREE from './vendor/three.module.js';
import {clipSurface,SURFACE_SPAN} from './nail-form.js';
import {drawArtwork,objectDimension} from './objects.js';
export function createObjectVisuals(){
 const textures=new Map(),masks=new Map(),materials=new Set(),hover={value:new THREE.Vector2()};
 const plane=new THREE.PlaneGeometry(1,1),facet=new THREE.BufferGeometry();facet.setAttribute('position',new THREE.Float32BufferAttribute([-.5,-.5,0,.5,-.5,0,.5,.5,0,-.5,.5,0,0,0,.11],3));facet.setAttribute('uv',new THREE.Float32BufferAttribute([0,0,1,0,1,1,0,1,.5,.5],2));facet.setIndex([0,1,4,1,2,4,2,3,4,3,0,4]);facet.computeVertexNormals();
 function mask(form,id){const cached=masks.get(id);if(cached?.form===form)return cached.texture;cached?.texture.dispose();const cv=document.createElement('canvas');cv.width=256;cv.height=256*SURFACE_SPAN;const ctx=cv.getContext('2d');clipSurface(ctx,form,256);ctx.fillStyle='#fff';ctx.fillRect(0,0,cv.width,cv.height);const texture=new THREE.CanvasTexture(cv);masks.set(id,{form,texture});return texture;}
 function make(c){const key=JSON.stringify([c.type,c.shape,c.color,c.motif,c.letter,c.finish]);let texture=textures.get(key);if(!texture){const cv=document.createElement('canvas');cv.width=cv.height=256;const ctx=cv.getContext('2d');ctx.translate(128,128);ctx.scale(7.4,7.4);drawArtwork(ctx,c);texture=new THREE.CanvasTexture(cv);texture.colorSpace=THREE.SRGBColorSpace;textures.set(key,texture);}
 const isSticker=c.type==='sticker',dimension=objectDimension(c),material=new THREE.ShaderMaterial({transparent:true,depthWrite:false,side:THREE.DoubleSide,uniforms:{art:{value:texture},nailMask:{value:texture},clipped:{value:0},center:{value:new THREE.Vector2()},basis:{value:new THREE.Vector4()},hover,cure:{value:0},shine:{value:isSticker?0:c.shape==='statement'?.10:.045}},vertexShader:'varying vec2 tex;void main(){tex=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:`uniform sampler2D art;uniform sampler2D nailMask;uniform float clipped;uniform vec2 center;uniform vec4 basis;uniform vec2 hover;uniform float shine;uniform float cure;varying vec2 tex;void main(){vec4 c=texture2D(art,tex);if(clipped>.5){vec2 p=tex-.5;vec2 uv=center+vec2(basis.x*p.x+basis.z*p.y,basis.y*p.x+basis.w*p.y);if(uv.x<0.||uv.x>1.||uv.y<0.||uv.y>3.)discard;c.a*=texture2D(nailMask,vec2(uv.x,1.-uv.y/3.)).a;}if(c.a<.01)discard;float glint=exp(-pow((tex.x-.32-hover.x*.09+(tex.y-.5)*.35)*20.,2.));c.rgb+=glint*shine+cure*.035;gl_FragColor=c;#include <colorspace_fragment>}`.replace('#include','\n#include')});materials.add(material);
 const group=new THREE.Group(),mesh=new THREE.Mesh(isSticker?plane:facet,material);mesh.scale.set(dimension,dimension,isSticker?1:dimension*.35);mesh.position.z=isSticker?.12:1.1;group.add(mesh);group.userData.illustrated=mesh;return group;}
 function position(body,c,form){const mesh=body.userData.illustrated;if(!mesh)return;mesh.renderOrder=100+(c.order||0);if(c.type==='sticker'){const d=objectDimension(c)*c.scale,co=Math.cos(c.rotation),si=Math.sin(c.rotation),w=form.naturalNailBounds.width,h=form.naturalNailBounds.height,u=mesh.material.uniforms;u.clipped.value=1;u.nailMask.value=mask(form,c.nailId);u.center.value.set(c.u,c.v);u.basis.value.set(co*d/w,-si*d/h,-si*d/w,-co*d/h);}}
 return {make,position,hover(x,y){hover.value.set(x,y);},cure(v){for(const m of materials)m.uniforms.cure.value=v;},dispose(body){const m=body.userData.illustrated?.material;if(m){materials.delete(m);m.dispose();}}};
}
